import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type WineCategory = 'Rosso' | 'Bianco' | 'Rosato' | 'Bollicine';

export interface Product {
  id: string;
  name: string;
  slug: string;
  vintage: number;
  grape: string;
  category: WineCategory;
  priceInCents: number;
  stock: number;
  image: string;
  lifestyleImage: string;
  isAvailable: boolean;
  sulfites: boolean;
  alcohol: string;
  allergens: string;
  description: string;
  tastingNotes: {
    visual: string;
    olfactory: string;
    gustatory: string;
  };
  pairings: string[];
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  email: string;
  role: 'ADMIN' | 'CUSTOMER';
}

export enum OrderStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  SHIPPED = 'SHIPPED'
}

export interface Order {
  id: string;
  userId: string;
  items: CartItem[];
  totalAmount: number;
  status: OrderStatus;
  createdAt: string;
}

