const App: React.FC = () => {
  const [isAgeVerified, setIsAgeVerified] = useState<boolean>(() => {
    return localStorage.getItem('ageVerified') === 'true';
  });
  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('cart');
    return saved ? JSON.parse(saved) : [];
  });
  const [user, setUser] = useState<User | null>(null); // Admin mock

  useEffect(() => {
    localStorage.setItem('cart', JSON.stringify(cart));
  }, [cart]);

  const handleAgeVerify = () => {
    setIsAgeVerified(true);
    localStorage.setItem('ageVerified', 'true');
  };

  const addToCart = (product: Product, quantity: number = 1) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleLogout = () => {
    setUser(null);
  };

  if (!isAgeVerified) {
    return <AgeVerification onConfirm={handleAgeVerify} />;
  }

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col font-sans">
        <Navbar cartCount={cart.reduce((acc, item) => acc + item.quantity, 0)} user={user} onLogout={handleLogout} />

        <main className="flex-grow pt-20">
          <Routes>
            <Route path="/" element={<Home wines={WINES} />} />
            <Route path="/shop" element={<Shop wines={WINES} onAddToCart={addToCart} />} />
            <Route path="/shop/:slug" element={<ProductDetail wines={WINES} onAddToCart={addToCart} />} />
            <Route path="/cantina" element={<Cantina />} />
            <Route path="/territorio" element={<Territorio />} />
            <Route path="/carrello" element={<Cart cart={cart} onUpdateQty={updateQuantity} />} />
            <Route path="/checkout" element={<Checkout cart={cart} />} />
            <Route path="/admin" element={<Admin wines={WINES} />} />
          </Routes>
        </main>

        <AISommelier cart={cart} />
        <Footer />
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MessageCircle, X, Send, Loader2, Wine } from 'lucide-react';
import { CartItem } from '../types';

interface AISommelierProps {
  cart: CartItem[];
}

const AISommelier: React.FC<AISommelierProps> = ({ cart }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const cartContext = cart.length > 0 
        ? `L'utente ha nel carrello: ${cart.map(i => `${i.name} (${i.vintage})`).join(', ')}.` 
        : "Il carrello dell'utente è vuoto.";

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `Sei il Sommelier Virtuale della Cantina Terre del Poggio. 
          Aiuti gli utenti a scegliere il vino perfetto o ad abbinare i vini della cantina ai piatti.
          ${cartContext}
          Parla in modo elegante, esperto ma accogliente. Focus sul territorio di Poggiofiorito e l'influenza del mare Adriatico.
          Vini disponibili: Montepulciano, Pecorino, Cerasuolo, Trebbiano, Cococciola, Passerina.
          Rispondi in italiano.`,
        },
      });

      const aiText = response.text || "Mi dispiace, sto avendo difficoltà a connettermi alla cantina. Riprova più tardi.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'ai', text: "Si è verificato un errore nella degustazione virtuale. Riprova più tardi." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {!isOpen && (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-burgundy text-white p-4 rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center space-x-2 group"
        >
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 whitespace-nowrap text-sm font-bold tracking-widest uppercase pl-0 group-hover:pl-2">Sommelier AI</span>
          <MessageCircle size={24} />
        </button>
      )}

      {isOpen && (
        <div className="bg-cream w-[350px] sm:w-[400px] h-[500px] rounded-2xl shadow-2xl flex flex-col border border-burgundy/10 overflow-hidden">
          <div className="bg-burgundy p-4 flex justify-between items-center text-white">
            <div className="flex items-center space-x-2">
              <Wine className="text-gold" />
              <h3 className="font-serif text-lg font-bold">Sommelier Virtuale</h3>
            </div>
            <button onClick={() => setIsOpen(false)}><X size={20} /></button>
          </div>

          <div ref={scrollRef} className="flex-grow overflow-y-auto p-4 space-y-4">
            {messages.length === 0 && (
              <div className="text-center mt-10 space-y-2">
                <Wine className="mx-auto text-gold mb-4" size={48} />
                <p className="text-earth font-serif text-lg italic">"Ogni vino ha una storia, vuoi che ti aiuti a trovare la tua?"</p>
                <p className="text-sm text-earth/60">Chiedimi abbinamenti o consigli sui nostri vini.</p>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-lg text-sm ${
                  m.role === 'user' ? 'bg-burgundy text-white' : 'bg-gold/10 text-earth border border-gold/20'
                }`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-gold/10 p-3 rounded-lg">
                  <Loader2 size={20} className="animate-spin text-gold" />
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t border-burgundy/10 flex space-x-2">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Chiedi al sommelier..."
              className="flex-grow bg-cream rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-burgundy"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading}
              className="bg-burgundy text-white p-2 rounded-full hover:bg-earth transition-colors disabled:opacity-50"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AISommelier;

import React, { useState, useMemo } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { Filter, ChevronDown, SlidersHorizontal, Plus, ShoppingBag } from 'lucide-react';
import { Product, WineCategory } from '../types';

interface ShopProps {
  wines: Product[];
  onAddToCart: (product: Product) => void;
}

const Shop: React.FC<ShopProps> = ({ wines, onAddToCart }) => {
  const [searchParams] = useSearchParams();
  const initialCat = searchParams.get('cat') as WineCategory | null;

  const [selectedCategory, setSelectedCategory] = useState<WineCategory | 'All'>(initialCat || 'All');
  const [sortBy, setSortBy] = useState<'price-asc' | 'price-desc' | 'name'>('name');

  const categories: (WineCategory | 'All')[] = ['All', 'Rosso', 'Bianco', 'Rosato', 'Bollicine'];

  const filteredWines = useMemo(() => {
    let result = [...wines];
    if (selectedCategory !== 'All') {
      result = result.filter(w => w.category === selectedCategory);
    }

    if (sortBy === 'price-asc') result.sort((a, b) => a.priceInCents - b.priceInCents);
    if (sortBy === 'price-desc') result.sort((a, b) => b.priceInCents - a.priceInCents);
    if (sortBy === 'name') result.sort((a, b) => a.name.localeCompare(b.name));

    return result;
  }, [wines, selectedCategory, sortBy]);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="text-center space-y-4">
        <h1 className="text-5xl font-serif text-burgundy italic">La nostra Cantina</h1>
        <p className="text-gold tracking-widest uppercase text-sm font-bold">Esplora la collezione completa</p>
      </div>

      {/* Filters & Sorting */}
      <div className="flex flex-col md:flex-row justify-between items-center border-y border-burgundy/10 py-6 gap-6">
        <div className="flex flex-wrap justify-center gap-4">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-6 py-2 text-xs font-bold tracking-widest uppercase rounded-full transition-all border ${
                selectedCategory === cat 
                ? 'bg-burgundy text-white border-burgundy' 
                : 'bg-white text-earth border-burgundy/10 hover:border-gold'
              }`}
            >
              {cat === 'All' ? 'Tutti i vini' : cat}
            </button>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <SlidersHorizontal size={18} className="text-gold" />
          <select 
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
            className="bg-transparent text-sm font-bold uppercase tracking-wider text-earth focus:outline-none"
          >
            <option value="name">Nome (A-Z)</option>
            <option value="price-asc">Prezzo: Crescente</option>
            <option value="price-desc">Prezzo: Decrescente</option>
          </select>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-12 gap-y-16">
        {filteredWines.map(wine => (
          <div key={wine.id} className="group flex flex-col">
            <div className="relative aspect-[3/4] overflow-hidden bg-cream mb-6">
              <Link to={`/shop/${wine.slug}`}>
                <img 
                  src={wine.image} 
                  alt={wine.name}
                  className="w-full h-full object-cover transition-all duration-700 group-hover:scale-105"
                />
                {/* Secondary Image on Hover */}
                <img 
                  src={wine.lifestyleImage} 
                  alt={`${wine.name} lifestyle`}
                  className="absolute inset-0 w-full h-full object-cover opacity-0 group-hover:opacity-100 transition-opacity duration-700"
                />
              </Link>
              <button 
                onClick={() => onAddToCart(wine)}
                className="absolute bottom-4 right-4 bg-burgundy text-white p-4 rounded-full shadow-lg opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all hover:bg-gold"
              >
                <Plus size={24} />
              </button>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <p className="text-[10px] text-gold uppercase tracking-[0.3em] font-bold">{wine.category}</p>
                  <Link to={`/shop/${wine.slug}`} className="block">
                    <h3 className="text-xl font-serif text-burgundy italic group-hover:text-gold transition-colors">
                      {wine.name}
                    </h3>
                  </Link>
                  <p className="text-sm text-earth/60 italic">{wine.grape}, {wine.vintage}</p>
                </div>
                <p className="text-lg font-bold text-burgundy">€ {(wine.priceInCents / 100).toFixed(2)}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {filteredWines.length === 0 && (
        <div className="text-center py-20 space-y-4">
          <Wine size={48} className="mx-auto text-gold/20" />
          <p className="text-earth/60 italic">Nessun vino trovato per questa categoria.</p>
          <button onClick={() => setSelectedCategory('All')} className="text-burgundy underline font-bold text-sm tracking-widest uppercase">
            Mostra tutti i vini
          </button>
        </div>
      )}
    </div>
  );
};

export default Shop;

import React, { useState, useMemo } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { Filter, ChevronDown, SlidersHorizontal, Plus, ShoppingBag, Wine } from 'lucide-react';
import { Product, WineCategory } from '../types';

interface ShopProps {
  wines: Product[];
  onAddToCart: (product: Product) => void;
}

const Shop: React.FC<ShopProps> = ({ wines, onAddToCart }) => {
  const [searchParams] = useSearchParams();
  const initialCat = searchParams.get('cat') as WineCategory | null;

  const [selectedCategory, setSelectedCategory] = useState<WineCategory | 'All'>(initialCat || 'All');
  const [sortBy, setSortBy] = useState<'price-asc' | 'price-desc' | 'name'>('name');

  const categories: (WineCategory | 'All')[] = ['All', 'Rosso', 'Bianco', 'Rosato', 'Bollicine'];

  const filteredWines = useMemo(() => {
    let result = [...wines];
    if (selectedCategory !== 'All') {
      result = result.filter(w => w.category === selectedCategory);
    }

    if (sortBy === 'price-asc') result.sort((a, b) => a.priceInCents - b.priceInCents);
    if (sortBy === 'price-desc') result.sort((a, b) => b.priceInCents - a.priceInCents);
    if (sortBy === 'name') result.sort((a, b) => a.name.localeCompare(b.name));

    return result;
  }, [wines, selectedCategory, sortBy]);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="text-center space-y-4">
        <h1 className="text-5xl font-serif text-burgundy italic">La nostra Cantina</h1>
        <p className="text-gold tracking-widest uppercase text-sm font-bold">Esplora la collezione completa</p>
      </div>

      {/* Filters & Sorting */}
      <div className="flex flex-col md:flex-row justify-between items-center border-y border-burgundy/10 py-6 gap-6">
        <div className="flex flex-wrap justify-center gap-4">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-6 py-2 text-xs font-bold tracking-widest uppercase rounded-full transition-all border ${
                selectedCategory === cat 
                ? 'bg-burgundy text-white border-burgundy' 
                : 'bg-white text-earth border-burgundy/10 hover:border-gold'
              }`}
            >
              {cat === 'All' ? 'Tutti i vini' : cat}
            </button>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <SlidersHorizontal size={18} className="text-gold" />
          <select 
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
            className="bg-transparent text-sm font-bold uppercase tracking-wider text-earth focus:outline-none"
          >
            <option value="name">Nome (A-Z)</option>
            <option value="price-asc">Prezzo: Crescente</option>
            <option value="price-desc">Prezzo: Decrescente</option>
          </select>
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-12 gap-y-16">
        {filteredWines.map(wine => (
          <div key={wine.id} className="group flex flex-col">
            <div className="relative aspect-[3/4] overflow-hidden bg-cream mb-6">
              <Link to={`/shop/${wine.slug}`}>
                <img 
