import React, { useState, useEffect } from 'react';
import { ShieldCheck, CreditCard, Truck, User as UserIcon } from 'lucide-react';
import { CartItem, User, Order, OrderStatus } from '../types';
import { useNavigate } from 'react-router-dom';

interface CheckoutProps {
  cart: CartItem[];
  user: User | null;
  onOrderComplete: (order: Order) => void;
}

const Checkout: React.FC<CheckoutProps> = ({ cart, user, onOrderComplete }) => {
  const [isSuccess, setIsSuccess] = useState(false);
  const navigate = useNavigate();

  // Prefill if logged in
  const [formData, setFormData] = useState({
    name: user?.profile?.name || '',
    surname: user?.profile?.surname || '',
    email: user?.email || '',
    address: user?.profile?.address || '',
    city: user?.profile?.city || '',
    zip: user?.profile?.zip || ''
  });

  const subtotal = cart.reduce((acc, item) => acc + (item.priceInCents * item.quantity), 0);
  const shipping = subtotal > 15000 ? 0 : 1500;
  const total = subtotal + shipping;

  const handlePay = (e: React.FormEvent) => {
    e.preventDefault();

    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      userId: user?.id || 'guest',
      userEmail: formData.email,
      items: cart,
      totalAmount: total,
      status: OrderStatus.PAID,
      createdAt: new Date().toISOString()
    };

    onOrderComplete(newOrder);
    setIsSuccess(true);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-32 text-center space-y-8">
        <div className="mx-auto w-20 h-20 bg-green-100 flex items-center justify-center rounded-full text-green-600">
          <ShieldCheck size={48} />
