const App: React.FC = () => {
  // Global States (Simulating Database)
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('currentUser');
    return saved ? JSON.parse(saved) : null;
  });

  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('products');
    return saved ? JSON.parse(saved) : WINES;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [coupons, setCoupons] = useState<Coupon[]>(() => {
    const saved = localStorage.getItem('coupons');
    return saved ? JSON.parse(saved) : [
      { id: '1', code: 'WELCOME10', discount: 10, type: 'PERCENT' },
      { id: '2', code: 'PROMO5', discount: 500, type: 'FIXED' }
    ];
  });

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('cart');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('cart', JSON.stringify(cart));
    localStorage.setItem('products', JSON.stringify(products));
    localStorage.setItem('orders', JSON.stringify(orders));
    localStorage.setItem('coupons', JSON.stringify(coupons));
    if (user) localStorage.setItem('currentUser', JSON.stringify(user));
    else localStorage.removeItem('currentUser');
  }, [cart, products, orders, coupons, user]);

  const addToCart = (product: Product, quantity: number = 1) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + quantity } : item);
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleLogout = () => {
    setUser(null);
  };

  const addOrder = (order: Order) => {
    setOrders(prev => [order, ...prev]);
    setCart([]);
  };

  return (
    <HashRouter>
      <ScrollToTop />
      <div className="min-h-screen flex flex-col font-sans">
        <Navbar cartCount={cart.reduce((acc, item) => acc + item.quantity, 0)} user={user} onLogout={handleLogout} />

        <main className="flex-grow pt-20">
          <Routes>
            <Route path="/" element={<Home wines={products} />} />
            <Route path="/shop" element={<Shop wines={products} onAddToCart={addToCart} />} />
            <Route path="/shop/:slug" element={<ProductDetail wines={products} onAddToCart={addToCart} />} />
            <Route path="/cantina" element={<Cantina />} />
            <Route path="/territorio" element={<Territorio />} />
            <Route path="/carrello" element={<Cart cart={cart} onUpdateQty={updateQuantity} />} />
            <Route path="/checkout" element={<Checkout cart={cart} user={user} onOrderComplete={addOrder} />} />
            <Route path="/auth" element={<AuthPage onLogin={setUser} />} />

            {/* Protected Routes */}
            <Route path="/account" element={user ? <Account user={user} orders={orders.filter(o => o.userId === user.id)} onUpdateUser={setUser} /> : <Navigate to="/auth" />} />
            <Route path="/admin" element={user?.role === 'ADMIN' ? <Admin products={products} setProducts={setProducts} orders={orders} coupons={coupons} setCoupons={setCoupons} /> : <Navigate to="/" />} />
          </Routes>
        </main>

        <AISommelier cart={cart} />
        <footer className="bg-burgundy text-cream pt-16 pb-8">
