                <li><Link to="/privacy" className="hover:text-gold">Privacy & Cookie Policy</Link></li>
              </ul>
            </div>
          </div>
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pt-8 border-t border-cream/10 text-center text-[10px] text-cream/50 uppercase tracking-widest">
