import React from 'react';
import { Link } from 'react-router-dom';
import { Trash2, Minus, Plus, ShoppingBag, ArrowRight, Truck } from 'lucide-react';
import { CartItem, ShippingSettings } from '../types';

interface CartProps {
  cart: CartItem[];
  onUpdateQty: (id: string, delta: number) => void;
  shippingSettings: ShippingSettings;
}

const Cart: React.FC<CartProps> = ({ cart, onUpdateQty, shippingSettings }) => {
  const subtotal = cart.reduce((acc, item) => acc + (item.priceInCents * item.quantity), 0);

  // Default shipping estimate (Italy)
  const isFree = subtotal >= shippingSettings.freeShippingThreshold;
  const estimatedShipping = isFree ? 0 : shippingSettings.italyShippingCost;
  const total = subtotal + estimatedShipping;

  const missingForFree = shippingSettings.freeShippingThreshold - subtotal;

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 text-center space-y-8">
        <div className="mx-auto w-24 h-24 bg-burgundy/5 flex items-center justify-center rounded-full text-burgundy/20">
          <ShoppingBag size={48} />
        </div>
        <div className="space-y-2">
          <h1 className="text-3xl font-serif text-burgundy">Il tuo carrello è vuoto</h1>
          <p className="text-earth/60">Sembra che tu non abbia ancora scelto il tuo vino preferito.</p>
        </div>
        <Link to="/shop" className="inline-block bg-burgundy text-white px-10 py-4 rounded font-bold tracking-widest uppercase hover:bg-gold transition-all">
          Vai alla Boutique
        </Link>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <h1 className="text-4xl font-serif text-burgundy italic mb-12">Il tuo Carrello</h1>

      {!isFree && (
        <div className="bg-gold/10 border border-gold/20 p-6 rounded-lg mb-12 flex items-center gap-4 animate-pulse">
          <Truck className="text-gold" size={24} />
          <p className="text-sm text-earth">
            Ti mancano solo <span className="font-bold">€ {(missingForFree / 100).toFixed(2)}</span> per sbloccare la <span className="font-bold uppercase">Spedizione Gratuita!</span>
          </p>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-16">
        <div className="lg:col-span-2 space-y-8">
          {cart.map(item => (
            <div key={item.id} className="flex flex-col sm:flex-row items-center space-y-4 sm:space-y-0 sm:space-x-6 border-b border-burgundy/10 pb-8">
              <div className="w-24 h-32 bg-cream rounded-sm overflow-hidden flex-shrink-0">
                <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
              </div>
              <div className="flex-grow space-y-1 text-center sm:text-left">
                <p className="text-[10px] text-gold uppercase tracking-widest font-bold">{item.category}</p>
                <h3 className="text-lg font-serif text-burgundy">{item.name}</h3>
                <p className="text-xs text-earth/50">{item.grape}, {item.vintage}</p>
              </div>
              <div className="flex items-center border border-burgundy/20 rounded-full px-3 py-1">
                <button onClick={() => onUpdateQty(item.id, -1)} className="p-1 hover:text-gold"><Minus size={14}/></button>
                <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                <button onClick={() => onUpdateQty(item.id, 1)} className="p-1 hover:text-gold"><Plus size={14}/></button>
              </div>
              <div className="text-right w-full sm:w-24">
                <p className="font-bold text-burgundy">€ {((item.priceInCents * item.quantity) / 100).toFixed(2)}</p>
              </div>
              <button onClick={() => onUpdateQty(item.id, -item.quantity)} className="text-earth/30 hover:text-burgundy">
                <Trash2 size={20} />
              </button>
            </div>
          ))}
        </div>

        <div className="bg-burgundy/5 p-8 rounded-sm h-fit space-y-8">
          <h2 className="text-xl font-serif text-burgundy italic">Riepilogo Ordine</h2>
          <div className="space-y-4 text-sm">
            <div className="flex justify-between text-earth/70">
              <span>Subtotale</span>
              <span>€ {(subtotal / 100).toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-earth/70">
              <span className="flex items-center gap-2">Spedizione (Estima Italia)</span>
              <span>{estimatedShipping === 0 ? 'GRATUITA' : `€ ${(estimatedShipping / 100).toFixed(2)}`}</span>
            </div>
            <div className="pt-4 border-t border-burgundy/10 flex justify-between font-bold text-lg text-burgundy">
              <span>Totale</span>
              <span>€ {(total / 100).toFixed(2)}</span>
            </div>
          </div>
          <Link 
            to="/checkout" 
            className="w-full block bg-burgundy text-white py-4 rounded text-center font-bold tracking-widest uppercase hover:bg-gold transition-all shadow-lg"
          >
            Procedi al Checkout
          </Link>
          <div className="space-y-4 pt-4 text-[10px] text-earth/50 uppercase tracking-widest leading-relaxed">
