import React, { useState } from 'react';
import { ShieldCheck, CreditCard, Truck, Globe, ChevronDown } from 'lucide-react';
import { CartItem, User, Order, OrderStatus, ShippingSettings } from '../types';
import { useNavigate } from 'react-router-dom';

interface CheckoutProps {
  cart: CartItem[];
  user: User | null;
  onOrderComplete: (order: Order) => void;
  shippingSettings: ShippingSettings;
}

const Checkout: React.FC<CheckoutProps> = ({ cart, user, onOrderComplete, shippingSettings }) => {
  const [isSuccess, setIsSuccess] = useState(false);
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    name: user?.profile?.name || '',
    surname: user?.profile?.surname || '',
    email: user?.email || '',
    address: user?.profile?.address || '',
    city: user?.profile?.city || '',
    zip: user?.profile?.zip || '',
    country: user?.profile?.country || 'Italia'
  });

  const subtotal = cart.reduce((acc, item) => acc + (item.priceInCents * item.quantity), 0);

  // Calculate dynamic shipping
  const getShippingCost = () => {
    if (subtotal >= shippingSettings.freeShippingThreshold) return 0;
    if (formData.country === 'Italia') return shippingSettings.italyShippingCost;
    return shippingSettings.internationalShippingCost;
  };

  const shipping = getShippingCost();
  const total = subtotal + shipping;

  const handlePay = (e: React.FormEvent) => {
    e.preventDefault();
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      userId: user?.id || 'guest',
      userEmail: formData.email,
      items: cart,
      totalAmount: total,
      shippingCost: shipping,
      status: OrderStatus.PAID,
      createdAt: new Date().toISOString(),
      shippingCountry: formData.country
    };
    onOrderComplete(newOrder);
    setIsSuccess(true);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-32 text-center space-y-8">
        <div className="mx-auto w-20 h-20 bg-green-100 flex items-center justify-center rounded-full text-green-600">
          <ShieldCheck size={48} />
        </div>
        <div className="space-y-2">
          <h1 className="text-4xl font-serif text-burgundy italic">Ordine Confermato</h1>
          <p className="text-earth/60">Le tue bottiglie partiranno presto dai nostri vigneti verso <strong>{formData.country}</strong>.</p>
        </div>
        <div className="bg-burgundy/5 p-8 rounded border border-burgundy/10">
           <p className="text-[10px] uppercase font-bold tracking-widest text-earth/50">Dettagli Consegna</p>
           <p className="text-sm text-earth mt-2 font-bold">{formData.name} {formData.surname}</p>
           <p className="text-sm text-earth italic">{formData.address}, {formData.city}, {formData.country}</p>
        </div>
        <button onClick={() => navigate(user ? '/account' : '/')} className="bg-burgundy text-white px-8 py-4 rounded font-bold uppercase tracking-widest text-xs hover:bg-gold transition-all">
          {user ? 'Vai ai Miei Ordini' : 'Torna alla Boutique'}
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
        <form onSubmit={handlePay} className="space-y-12">
          <div className="space-y-8">
            <h2 className="text-2xl font-serif text-burgundy italic border-b border-burgundy/10 pb-4">Destinazione</h2>

            <div className="space-y-4">
              <div className="relative group">
                <label className="text-[10px] uppercase font-bold text-earth/50 mb-1 block">Paese di spedizione</label>
                <div className="relative">
                  <select 
                    value={formData.country} 
                    onChange={e => setFormData({...formData, country: e.target.value})}
                    className="w-full bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none appearance-none cursor-pointer pr-10"
                  >
                    {shippingSettings.supportedCountries.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <Globe className="absolute right-4 top-1/2 -translate-y-1/2 text-gold pointer-events-none" size={18} />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input type="text" placeholder="Nome" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="Cognome" required value={formData.surname} onChange={e => setFormData({...formData, surname: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="email" placeholder="Email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="sm:col-span-2 bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="Indirizzo" required value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="sm:col-span-2 bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="Città" required value={formData.city} onChange={e => setFormData({...formData, city: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="CAP" required value={formData.zip} onChange={e => setFormData({...formData, zip: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
              </div>
            </div>
          </div>

          <div className="space-y-8">
            <h2 className="text-2xl font-serif text-burgundy italic border-b border-burgundy/10 pb-4">Pagamento</h2>
            <div className="bg-white border border-burgundy/10 rounded-sm p-6 space-y-6">
              <div className="flex items-center space-x-4">
                <CreditCard size={24} className="text-gold" />
