                  <input type="text" placeholder="MM/AA" className="bg-cream rounded-sm p-4 text-sm" />
                  <input type="text" placeholder="CVC" className="bg-cream rounded-sm p-4 text-sm" />
                </div>
              </div>
            </div>
          </div>

          <button type="submit" className="w-full bg-burgundy text-white py-6 rounded font-bold tracking-widest uppercase hover:bg-gold transition-all shadow-xl">
            Ordine con obbligo di pagare — € {(total / 100).toFixed(2)}
          </button>
        </form>

        <div className="hidden lg:block">
           <div className="bg-white p-8 border border-burgundy/10 rounded-sm sticky top-32">
            <h3 className="text-xl font-serif text-burgundy italic mb-8">Riepilogo</h3>
            <div className="space-y-6 mb-8">
              {cart.map(item => (
                <div key={item.id} className="flex space-x-4">
                   <div className="w-12 h-16 bg-cream flex-shrink-0 rounded-sm overflow-hidden">
                     <img src={item.image} className="w-full h-full object-cover" />
                   </div>
                   <div className="flex-grow">
                     <p className="text-[10px] font-bold text-burgundy uppercase">{item.name}</p>
                     <p className="text-[10px] text-earth/50">{item.quantity} x € {(item.priceInCents / 100).toFixed(2)}</p>
