import React, { useState, useEffect } from 'react';
import { Product, Order, Coupon, WineCategory, ShippingSettings } from '../types';
import { Package, TrendingUp, Users, Settings, Plus, Edit, Trash2, ClipboardList, Tag, DollarSign, Save, Wine, X, Check, Truck, Globe } from 'lucide-react';

interface AdminProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  orders: Order[];
  coupons: Coupon[];
  setCoupons: React.Dispatch<React.SetStateAction<Coupon[]>>;
  shippingSettings: ShippingSettings;
  setShippingSettings: React.Dispatch<React.SetStateAction<ShippingSettings>>;
}

const Admin: React.FC<AdminProps> = ({ products, setProducts, orders, coupons, setCoupons, shippingSettings, setShippingSettings }) => {
  const [activeTab, setActiveTab] = useState<'products' | 'orders' | 'coupons' | 'shipping'>('products');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [countryInput, setCountryInput] = useState('');

  const saveShipping = (e: React.FormEvent) => {
    e.preventDefault();
    alert("Impostazioni di logistica salvate!");
  };

  const addCountry = () => {
    if (countryInput && !shippingSettings.supportedCountries.includes(countryInput)) {
      setShippingSettings({...shippingSettings, supportedCountries: [...shippingSettings.supportedCountries, countryInput]});
      setCountryInput('');
    }
  };

  const removeCountry = (c: string) => {
    setShippingSettings({...shippingSettings, supportedCountries: shippingSettings.supportedCountries.filter(country => country !== c)});
  };

  const deleteProduct = (id: string) => {
    if (confirm("Sei sicuro di voler eliminare questo vino dal catalogo?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const saveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    if (isAddingNew) {
      setProducts(prev => [...prev, { ...editingProduct, id: Math.random().toString(36).substr(2, 9) }]);
    } else {
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? editingProduct : p));
    }
    setEditingProduct(null);
    setIsAddingNew(false);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div className="space-y-2">
          <h1 className="text-4xl font-serif text-burgundy italic">Console Admin</h1>
          <p className="text-gold uppercase tracking-widest text-sm font-bold">Gestione Cantina</p>
        </div>

        <div className="flex bg-white rounded-full p-1 shadow-sm border border-burgundy/5 overflow-x-auto">
          <button onClick={() => setActiveTab('products')} className={`px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'products' ? 'bg-burgundy text-white' : 'text-earth/60'}`}>Vini</button>
          <button onClick={() => setActiveTab('orders')} className={`px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'orders' ? 'bg-burgundy text-white' : 'text-earth/60'}`}>Ordini</button>
          <button onClick={() => setActiveTab('coupons')} className={`px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'coupons' ? 'bg-burgundy text-white' : 'text-earth/60'}`}>Coupon</button>
          <button onClick={() => setActiveTab('shipping')} className={`px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'shipping' ? 'bg-burgundy text-white' : 'text-earth/60'}`}>Logistica</button>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-burgundy/5 overflow-hidden min-h-[500px]">
        {activeTab === 'products' && (
          <div className="overflow-x-auto">
             <div className="p-6 border-b border-burgundy/5 flex justify-between items-center">
                <h2 className="font-serif text-xl text-burgundy italic">Catalogo Etichette</h2>
                <button onClick={() => setIsAddingNew(true)} className="bg-burgundy text-white px-4 py-2 rounded text-[10px] font-bold uppercase tracking-widest hover:bg-gold transition-all">Nuovo Prodotto</button>
             </div>
             <table className="w-full text-left">
                <thead className="bg-burgundy/5 text-[10px] uppercase font-bold tracking-widest text-earth/50">
                  <tr><th className="px-6 py-4">Vino</th><th className="px-6 py-4">Prezzo</th><th className="px-6 py-4">Stock</th><th className="px-6 py-4 text-right">Azioni</th></tr>
                </thead>
                <tbody className="divide-y divide-burgundy/5">
                  {products.map(p => (
                    <tr key={p.id} className="hover:bg-burgundy/5">
                      <td className="px-6 py-4 flex items-center gap-3"><img src={p.image} className="w-8 h-10 object-cover rounded" /><div><p className="text-sm font-bold text-burgundy">{p.name}</p></div></td>
                      <td className="px-6 py-4 font-bold text-burgundy">€ {(p.priceInCents/100).toFixed(2)}</td>
                      <td className="px-6 py-4"><span className="text-[10px] font-bold text-green-600 uppercase">{p.stock} pz</span></td>
                      <td className="px-6 py-4 text-right flex justify-end gap-2"><button onClick={() => setEditingProduct(p)} className="p-2 text-earth/40 hover:text-gold"><Edit size={16}/></button><button onClick={() => deleteProduct(p.id)} className="p-2 text-earth/40 hover:text-red-600"><Trash2 size={16}/></button></td>
                    </tr>
                  ))}
                </tbody>
             </table>
          </div>
        )}

        {activeTab === 'shipping' && (
          <div className="p-8 space-y-12">
            <h2 className="font-serif text-2xl text-burgundy italic">Impostazioni Spedizione Internazionale</h2>
            <form onSubmit={saveShipping} className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] uppercase font-bold text-earth/50">Soglia Spedizione Gratuita (€)</label>
                  <input type="number" value={shippingSettings.freeShippingThreshold / 100} onChange={e => setShippingSettings({...shippingSettings, freeShippingThreshold: parseInt(e.target.value) * 100})} className="w-full bg-cream p-4 rounded text-sm focus:outline-none focus:ring-1 focus:ring-burgundy" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] uppercase font-bold text-earth/50">Costo Spedizione Italia (€)</label>
                  <input type="number" value={shippingSettings.italyShippingCost / 100} onChange={e => setShippingSettings({...shippingSettings, italyShippingCost: parseInt(e.target.value) * 100})} className="w-full bg-cream p-4 rounded text-sm focus:outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] uppercase font-bold text-earth/50">Costo Spedizione Estero (€)</label>
                  <input type="number" value={shippingSettings.internationalShippingCost / 100} onChange={e => setShippingSettings({...shippingSettings, internationalShippingCost: parseInt(e.target.value) * 100})} className="w-full bg-cream p-4 rounded text-sm focus:outline-none" />
                </div>
                <button type="submit" className="bg-burgundy text-white px-8 py-4 rounded text-xs font-bold uppercase tracking-widest hover:bg-gold transition-all flex items-center gap-2"><Save size={16} /> Salva Configurazione</button>
              </div>

              <div className="space-y-6">
                <h3 className="text-lg font-serif text-burgundy italic flex items-center gap-2"><Globe size={18} className="text-gold" /> Paesi Supportati</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Aggiungi Nazione..." value={countryInput} onChange={e => setCountryInput(e.target.value)} className="flex-grow bg-cream p-4 rounded text-sm focus:outline-none" />
                  <button type="button" onClick={addCountry} className="bg-gold text-white px-4 rounded font-bold uppercase text-[10px]">Aggiungi</button>
                </div>
                <div className="flex flex-wrap gap-3">
                  {shippingSettings.supportedCountries.map(c => (
                    <span key={c} className="bg-burgundy/5 border border-burgundy/10 px-4 py-2 rounded-full text-xs font-bold text-burgundy flex items-center gap-2">
                      {c} <button type="button" onClick={() => removeCountry(c)}><X size={12} className="hover:text-red-600" /></button>
                    </span>
                  ))}
                </div>
              </div>
            </form>
          </div>
        )}

        {activeTab === 'orders' && (
          <div className="p-8 space-y-4">
            <h2 className="font-serif text-xl text-burgundy italic">Storico Vendite</h2>
            {orders.length === 0 ? <p className="text-center py-10 italic text-earth/40">Nessun ordine.</p> : (
              <div className="space-y-4">
                {orders.map(o => (
                  <div key={o.id} className="border border-burgundy/5 p-4 rounded flex justify-between items-center bg-burgundy/5">
                    <div>
                      <p className="text-xs font-bold text-burgundy uppercase">Ordine #{o.id.slice(0,8)}</p>
                      <p className="text-[10px] text-earth/60 italic">{o.userEmail} • Destinazione: <strong>{o.shippingCountry}</strong></p>
                    </div>
                    <p className="font-bold text-burgundy">€ {(o.totalAmount/100).toFixed(2)}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {editingProduct && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-burgundy/40 backdrop-blur-sm p-4 animate-in fade-in">
          <div className="bg-white w-full max-w-2xl rounded-lg shadow-2xl p-8 space-y-8 overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-serif text-burgundy italic">Modifica Etichetta</h2>
            <form onSubmit={saveProduct} className="space-y-4">
              <input type="text" value={editingProduct.name} onChange={e => setEditingProduct({...editingProduct, name: e.target.value})} className="w-full bg-cream p-4 rounded text-sm" />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={editingProduct.priceInCents/100} onChange={e => setEditingProduct({...editingProduct, priceInCents: parseInt(e.target.value)*100})} className="bg-cream p-4 rounded text-sm" />
                <input type="number" value={editingProduct.stock} onChange={e => setEditingProduct({...editingProduct, stock: parseInt(e.target.value)})} className="bg-cream p-4 rounded text-sm" />
              </div>
              <div className="flex gap-4">
                <button type="submit" className="flex-grow bg-burgundy text-white py-4 rounded font-bold uppercase text-[10px]">Salva</button>
                <button type="button" onClick={() => setEditingProduct(null)} className="px-8 border border-burgundy text-burgundy py-4 rounded font-bold uppercase text-[10px]">Annulla</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
