                    <button onClick={() => setStripeSettings({...stripeSettings, mode: 'live'})} className={`flex-grow py-3 rounded text-[10px] font-bold uppercase tracking-widest border transition-all ${stripeSettings.mode === 'live' ? 'bg-burgundy text-white border-burgundy' : 'border-burgundy/10 text-earth/60'}`}>Live Mode</button>
                  </div>
                </div>
              </div>

              <form className="space-y-6" onSubmit={(e) => { e.preventDefault(); alert('Chiavi API salvate con successo!'); }}>
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-earth/50">Stripe Publishable Key</label>
                  <input type="password" value={stripeSettings.publicKey} onChange={e => setStripeSettings({...stripeSettings, publicKey: e.target.value})} className="w-full bg-cream p-4 rounded text-sm font-mono focus:outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-earth/50">Stripe Secret Key</label>
                  <input type="password" value={stripeSettings.secretKey} onChange={e => setStripeSettings({...stripeSettings, secretKey: e.target.value})} className="w-full bg-cream p-4 rounded text-sm font-mono focus:outline-none" />
                </div>
                <div className="p-4 bg-orange-50 border border-orange-100 rounded text-[10px] text-orange-800 leading-relaxed italic">
                  Attenzione: Non condividere mai la Secret Key con nessuno. Le chiavi devono essere configurate correttamente per processare i pagamenti degli ordini.
                </div>
                <button type="submit" className="w-full bg-burgundy text-white py-4 rounded text-xs font-bold uppercase tracking-widest hover:bg-gold transition-all shadow-lg">Aggiorna Credenziali Stripe</button>
              </form>
            </div>
          </div>
        )}
      </div>

      {/* PRODUCT MODAL */}
      {editingProduct && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-burgundy/40 backdrop-blur-sm p-4 animate-in fade-in">
          <div className="bg-white w-full max-w-2xl rounded-lg shadow-2xl p-8 space-y-8 overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-serif text-burgundy italic">Modifica Etichetta</h2>
            <form onSubmit={saveProduct} className="space-y-4">
              <input type="text" value={editingProduct.name} onChange={e => setEditingProduct({...editingProduct, name: e.target.value})} className="w-full bg-cream p-4 rounded text-sm" />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" value={editingProduct.priceInCents/100} onChange={e => setEditingProduct({...editingProduct, priceInCents: parseInt(e.target.value)*100})} className="bg-cream p-4 rounded text-sm" />
                <input type="number" value={editingProduct.stock} onChange={e => setEditingProduct({...editingProduct, stock: parseInt(e.target.value)})} className="bg-cream p-4 rounded text-sm" />
              </div>
              <div className="flex gap-4">
                <button type="submit" className="flex-grow bg-burgundy text-white py-4 rounded font-bold uppercase text-[10px]">Salva</button>
                <button type="button" onClick={() => setEditingProduct(null)} className="px-8 border border-burgundy text-burgundy py-4 rounded font-bold uppercase text-[10px]">Annulla</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};
export default Admin;

import React, { useState } from 'react';
import { ShieldCheck, CreditCard, Truck, Globe, ChevronDown, Phone } from 'lucide-react';
import { CartItem, User, Order, OrderStatus, ShippingSettings } from '../types';
import { useNavigate } from 'react-router-dom';

interface CheckoutProps {
  cart: CartItem[];
  user: User | null;
  onOrderComplete: (order: Order) => void;
  shippingSettings: ShippingSettings;
}

const Checkout: React.FC<CheckoutProps> = ({ cart, user, onOrderComplete, shippingSettings }) => {
  const [isSuccess, setIsSuccess] = useState(false);
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    name: user?.profile?.name || '',
    surname: user?.profile?.surname || '',
    email: user?.email || '',
    phone: user?.profile?.phone || '',
    address: user?.profile?.address || '',
    city: user?.profile?.city || '',
    zip: user?.profile?.zip || '',
    country: user?.profile?.country || 'Italia'
  });

  const [paymentData, setPaymentData] = useState({
    cardNumber: '',
    expiry: '',
    cvc: ''
  });

  const subtotal = cart.reduce((acc, item) => acc + (item.priceInCents * item.quantity), 0);

  const getShippingCost = () => {
    if (subtotal >= shippingSettings.freeShippingThreshold) return 0;
    if (formData.country === 'Italia') return shippingSettings.italyShippingCost;
    return shippingSettings.internationalShippingCost;
  };

  const shipping = getShippingCost();
  const total = subtotal + shipping;

  const handlePay = (e: React.FormEvent) => {
    e.preventDefault();
    const newOrder: Order = {
      id: 'ORD-' + Math.random().toString(36).substr(2, 9).toUpperCase(),
      userId: user?.id || 'guest',
      userEmail: formData.email,
      userName: `${formData.name} ${formData.surname}`,
      userPhone: formData.phone,
      userAddress: `${formData.address}, ${formData.city} (${formData.zip})`,
      items: cart,
      totalAmount: total,
      shippingCost: shipping,
      status: OrderStatus.PAID,
      createdAt: new Date().toISOString(),
      shippingCountry: formData.country
    };
    onOrderComplete(newOrder);
    setIsSuccess(true);
  };

  if (isSuccess) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-32 text-center space-y-8">
        <div className="mx-auto w-20 h-20 bg-green-100 flex items-center justify-center rounded-full text-green-600">
          <ShieldCheck size={48} />
        </div>
        <div className="space-y-2">
          <h1 className="text-4xl font-serif text-burgundy italic">Ordine Confermato</h1>
          <p className="text-earth/60">Le tue bottiglie partiranno presto dai nostri vigneti verso <strong>{formData.country}</strong>.</p>
        </div>
        <div className="bg-burgundy/5 p-8 rounded border border-burgundy/10 text-left">
           <p className="text-[10px] uppercase font-bold tracking-widest text-earth/50">Riepilogo Spedizione</p>
           <p className="text-sm text-earth mt-2 font-bold">{formData.name} {formData.surname}</p>
           <p className="text-sm text-earth italic">{formData.address}, {formData.city}, {formData.country}</p>
           <p className="text-sm text-earth mt-1 flex items-center gap-2"><Phone size={12} className="text-gold" /> {formData.phone}</p>
        </div>
        <button onClick={() => navigate(user ? '/account' : '/')} className="bg-burgundy text-white px-8 py-4 rounded font-bold uppercase tracking-widest text-xs hover:bg-gold transition-all">
          {user ? 'Vai ai Miei Ordini' : 'Torna alla Boutique'}
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
        <form onSubmit={handlePay} className="space-y-12">
          <div className="space-y-8">
            <h2 className="text-2xl font-serif text-burgundy italic border-b border-burgundy/10 pb-4">Destinazione</h2>

            <div className="space-y-4">
              <div className="relative group">
                <label className="text-[10px] uppercase font-bold text-earth/50 mb-1 block">Paese di spedizione</label>
                <div className="relative">
                  <select 
                    value={formData.country} 
                    onChange={e => setFormData({...formData, country: e.target.value})}
                    className="w-full bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none appearance-none cursor-pointer pr-10"
                  >
                    {shippingSettings.supportedCountries.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                  <Globe className="absolute right-4 top-1/2 -translate-y-1/2 text-gold pointer-events-none" size={18} />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input type="text" placeholder="Nome" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="Cognome" required value={formData.surname} onChange={e => setFormData({...formData, surname: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="email" placeholder="Email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="sm:col-span-2 bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <div className="sm:col-span-2 relative">
                  <input type="tel" placeholder="Telefono (obbligatorio per il corriere)" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-white border border-burgundy/10 rounded-sm p-4 pl-12 text-sm focus:outline-none" />
                  <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-gold/50" size={16} />
                </div>
                <input type="text" placeholder="Indirizzo" required value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="sm:col-span-2 bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="Città" required value={formData.city} onChange={e => setFormData({...formData, city: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
                <input type="text" placeholder="CAP" required value={formData.zip} onChange={e => setFormData({...formData, zip: e.target.value})} className="bg-white border border-burgundy/10 rounded-sm p-4 text-sm focus:outline-none" />
              </div>
            </div>
          </div>

          <div className="space-y-8">
            <h2 className="text-2xl font-serif text-burgundy italic border-b border-burgundy/10 pb-4">Pagamento</h2>
            <div className="bg-white border border-burgundy/10 rounded-sm p-6 space-y-6">
              <div className="flex items-center space-x-4">
                <CreditCard size={24} className="text-gold" />
                <span className="font-bold tracking-widest text-sm uppercase">Carta di Credito / Apple Pay</span>
              </div>
              <div className="space-y-4">
                <input 
                  type="text" 
                  placeholder="•••• •••• •••• ••••" 
                  required
                  value={paymentData.cardNumber}
                  onChange={e => setPaymentData({...paymentData, cardNumber: e.target.value})}
                  className="w-full bg-cream rounded-sm p-4 text-sm focus:outline-none focus:ring-1 focus:ring-burgundy" 
                />
                <div className="grid grid-cols-2 gap-4">
                  <input 
                    type="text" 
                    placeholder="MM/AA" 
                    required
                    value={paymentData.expiry}
                    onChange={e => setPaymentData({...paymentData, expiry: e.target.value})}
                    className="bg-cream rounded-sm p-4 text-sm focus:outline-none focus:ring-1 focus:ring-burgundy" 
                  />
                  <input 
                    type="text" 
                    placeholder="CVC" 
                    required
                    value={paymentData.cvc}
                    onChange={e => setPaymentData({...paymentData, cvc: e.target.value})}
                    className="bg-cream rounded-sm p-4 text-sm focus:outline-none focus:ring-1 focus:ring-burgundy" 
                  />
                </div>
              </div>
            </div>
          </div>

          <button type="submit" className="w-full bg-burgundy text-white py-6 rounded font-bold tracking-widest uppercase hover:bg-gold transition-all shadow-xl">
            Ordine con obbligo di pagare — € {(total / 100).toFixed(2)}
          </button>
        </form>

        <div className="hidden lg:block">
           <div className="bg-white p-8 border border-burgundy/10 rounded-sm sticky top-32">
            <h3 className="text-xl font-serif text-burgundy italic mb-8">Riepilogo</h3>
            <div className="space-y-6 mb-8">
              {cart.map(item => (
                <div key={item.id} className="flex space-x-4">
                   <div className="w-12 h-16 bg-cream flex-shrink-0 rounded-sm overflow-hidden">
                     <img src={item.image} className="w-full h-full object-cover" />
                   </div>
                   <div className="flex-grow">
                     <p className="text-[10px] font-bold text-burgundy uppercase">{item.name}</p>
                     <p className="text-[10px] text-earth/50">{item.quantity} x € {(item.priceInCents / 100).toFixed(2)}</p>
                   </div>
                   <p className="text-xs font-bold text-earth">€ {((item.priceInCents * item.quantity) / 100).toFixed(2)}</p>
                </div>
              ))}
            </div>
            <div className="pt-8 border-t border-burgundy/10 space-y-2">
               <div className="flex justify-between text-xs text-earth/70">
                 <span>Subtotale</span>
                 <span>€ {(subtotal / 100).toFixed(2)}</span>
               </div>
               <div className="flex justify-between text-xs text-earth/70">
                 <span className="flex items-center gap-1">Spedizione per <span className="font-bold text-burgundy">{formData.country}</span></span>
                 <span>{shipping === 0 ? 'GRATIS' : `€ ${(shipping/100).toFixed(2)}`}</span>
               </div>
               <div className="flex justify-between font-bold text-xl text-burgundy pt-4">
                 <span>Totale</span>
                 <span>€ {(total / 100).toFixed(2)}</span>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Checkout;

import React, { useState } from 'react';
import { Product, Order, Coupon, ShippingSettings, WineCategory } from '../types';
import { Plus, Edit, Trash2, Save, X, Globe, CreditCard, Tag, ClipboardList, Package, DollarSign, Phone, MapPin, User as UserIcon, Wine, Image as ImageIcon, Info, GlassWater, Utensils } from 'lucide-react';

interface AdminProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  orders: Order[];
  coupons: Coupon[];
  setCoupons: React.Dispatch<React.SetStateAction<Coupon[]>>;
  shippingSettings: ShippingSettings;
  setShippingSettings: React.Dispatch<React.SetStateAction<ShippingSettings>>;
}

const Admin: React.FC<AdminProps> = ({ products, setProducts, orders, coupons, setCoupons, shippingSettings, setShippingSettings }) => {
  const [activeTab, setActiveTab] = useState<'products' | 'orders' | 'coupons' | 'shipping' | 'payments'>('products');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [countryInput, setCountryInput] = useState('');

  const [newCoupon, setNewCoupon] = useState({ code: '', discount: 0, type: 'PERCENT' as 'PERCENT' | 'FIXED' });
  const [stripeSettings, setStripeSettings] = useState({
    publicKey: 'pk_test_51Mz...',
    secretKey: 'sk_test_51Mz...',
    mode: 'test' as 'test' | 'live'
  });

  const saveShipping = (e: React.FormEvent) => {
    e.preventDefault();
    alert("Impostazioni di logistica salvate!");
  };

  const addCountry = () => {
    if (countryInput && !shippingSettings.supportedCountries.includes(countryInput)) {
      setShippingSettings({...shippingSettings, supportedCountries: [...shippingSettings.supportedCountries, countryInput]});
      setCountryInput('');
    }
  };

  const removeCountry = (c: string) => {
    setShippingSettings({...shippingSettings, supportedCountries: shippingSettings.supportedCountries.filter(country => country !== c)});
  };

  const deleteProduct = (id: string) => {
    if (confirm("Sei sicuro di voler eliminare questo vino dal catalogo?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const handleAddNew = () => {
    const newProd: Product = {
      id: '',
      name: '',
      slug: '',
      vintage: new Date().getFullYear(),
      grape: '',
      category: 'Rosso',
      priceInCents: 0,
      stock: 0,
      image: '',
      lifestyleImage: '',
      isAvailable: true,
      sulfites: true,
      alcohol: '13.0%',
      allergens: 'Contiene solfiti',
      description: '',
      tastingNotes: { visual: '', olfactory: '', gustatory: '' },
      pairings: []
    };
    setEditingProduct(newProd);
    setIsAddingNew(true);
  };

  const saveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const productToSave = {
      ...editingProduct,
      slug: editingProduct.slug || editingProduct.name.toLowerCase().replace(/ /g, '-').replace(/[^\w-]+/g, '')
    };

    if (isAddingNew) {
      setProducts(prev => [...prev, { ...productToSave, id: Math.random().toString(36).substr(2, 9) }]);
    } else {
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? productToSave : p));
    }
    setEditingProduct(null);
    setIsAddingNew(false);
  };

  const addCoupon = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCoupon.code) return;
    const coupon: Coupon = {
      id: Math.random().toString(36).substr(2, 9),
      code: newCoupon.code.toUpperCase(),
      discount: newCoupon.discount,
      type: newCoupon.type
    };
    setCoupons(prev => [...prev, coupon]);
    setNewCoupon({ code: '', discount: 0, type: 'PERCENT' });
  };

  const deleteCoupon = (id: string) => {
    setCoupons(prev => prev.filter(c => c.id !== id));
  };

