                <button onClick={handleAddNew} className="bg-burgundy text-white px-6 py-2 rounded text-[10px] font-bold uppercase tracking-widest hover:bg-gold transition-all flex items-center gap-2">
                  <Plus size={14} /> Nuova Etichetta
