              <div className="space-y-6">
                {orders.map(o => (
                  <div key={o.id} className="border border-burgundy/10 rounded-xl bg-white overflow-hidden shadow-sm hover:border-gold/30 transition-all">
                    <div className="bg-burgundy/5 p-6 border-b border-burgundy/10 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                      <div className="space-y-1">
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-burgundy uppercase bg-burgundy/10 px-3 py-1 rounded-full">#{o.id.slice(0,8)}</span>
