                              <span className="font-medium">{item.quantity}x <span className="text-burgundy font-bold">{item.name}</span> ({item.vintage})</span>
                              <span className="font-bold text-gold">€ {((item.priceInCents * item.quantity)/100).toFixed(2)}</span>
