                        <label className="text-[10px] uppercase font-bold text-earth/50">Gradazione Alcolica</label>
                        <input type="text" value={editingProduct.alcohol} onChange={e => setEditingProduct({...editingProduct, alcohol: e.target.value})} className="w-full bg-cream p-3 rounded text-sm focus:outline-none" placeholder="es. 13.5%" required />
