import React, { useState } from 'react';
import { Product, Order, Coupon, ShippingSettings, WineCategory } from '../types';
// Added Mail to the imports from lucide-react to fix 'Cannot find name Mail' error
import { Plus, Edit, Trash2, Save, X, Globe, CreditCard, Tag, ClipboardList, Package, DollarSign, Phone, MapPin, User as UserIcon, Wine, Image as ImageIcon, Info, GlassWater, Utensils, Mail } from 'lucide-react';

interface AdminProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  orders: Order[];
  coupons: Coupon[];
  setCoupons: React.Dispatch<React.SetStateAction<Coupon[]>>;
  shippingSettings: ShippingSettings;
  setShippingSettings: React.Dispatch<React.SetStateAction<ShippingSettings>>;
}

const Admin: React.FC<AdminProps> = ({ products, setProducts, orders, coupons, setCoupons, shippingSettings, setShippingSettings }) => {
  const [activeTab, setActiveTab] = useState<'products' | 'orders' | 'coupons' | 'shipping' | 'payments'>('products');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [countryInput, setCountryInput] = useState('');

  const [newCoupon, setNewCoupon] = useState({ code: '', discount: 0, type: 'PERCENT' as 'PERCENT' | 'FIXED' });
  const [stripeSettings, setStripeSettings] = useState({
    publicKey: 'pk_test_51Mz...',
    secretKey: 'sk_test_51Mz...',
    mode: 'test' as 'test' | 'live'
  });

  const handleAddNew = () => {
    const newProd: Product = {
      id: '',
      name: '',
      slug: '',
      vintage: new Date().getFullYear(),
      grape: '',
      category: 'Rosso',
      priceInCents: 0,
      stock: 0,
      image: '',
      lifestyleImage: '',
      isAvailable: true,
      sulfites: true,
      alcohol: '13.0%',
      allergens: 'Contiene solfiti',
      description: '',
      tastingNotes: { visual: '', olfactory: '', gustatory: '' },
      pairings: []
    };
    setEditingProduct(newProd);
    setIsAddingNew(true);
  };

  const saveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const productToSave = {
      ...editingProduct,
      slug: editingProduct.slug || editingProduct.name.toLowerCase().replace(/ /g, '-').replace(/[^\w-]+/g, '')
    };

    if (isAddingNew) {
      setProducts(prev => [...prev, { ...productToSave, id: Math.random().toString(36).substr(2, 9) }]);
    } else {
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? productToSave : p));
    }
    setEditingProduct(null);
    setIsAddingNew(false);
  };

  const deleteProduct = (id: string) => {
    if (confirm("Sei sicuro di voler eliminare questo vino dal catalogo?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const addCoupon = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCoupon.code) return;
    const coupon: Coupon = {
      id: Math.random().toString(36).substr(2, 9),
      code: newCoupon.code.toUpperCase(),
      discount: newCoupon.discount,
      type: newCoupon.type
    };
    setCoupons(prev => [...prev, coupon]);
    setNewCoupon({ code: '', discount: 0, type: 'PERCENT' });
  };

  const deleteCoupon = (id: string) => {
    setCoupons(prev => prev.filter(c => c.id !== id));
  };

  const addCountry = () => {
    if (countryInput && !shippingSettings.supportedCountries.includes(countryInput)) {
      setShippingSettings({...shippingSettings, supportedCountries: [...shippingSettings.supportedCountries, countryInput]});
      setCountryInput('');
    }
  };

  const removeCountry = (c: string) => {
    setShippingSettings({...shippingSettings, supportedCountries: shippingSettings.supportedCountries.filter(country => country !== c)});
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div className="space-y-2">
          <h1 className="text-4xl font-serif text-burgundy italic">Console Admin</h1>
          <p className="text-gold uppercase tracking-widest text-sm font-bold">Gestione Integrata Cantina</p>
        </div>

        <div className="flex bg-white rounded-full p-1 shadow-sm border border-burgundy/5 overflow-x-auto">
          {[
            { id: 'products', label: 'Vini', icon: Package },
            { id: 'orders', label: 'Ordini', icon: ClipboardList },
            { id: 'coupons', label: 'Coupon', icon: Tag },
            { id: 'shipping', label: 'Logistica', icon: Globe },
            { id: 'payments', label: 'Pagamenti', icon: CreditCard }
          ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)} 
              className={`flex items-center gap-2 px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-burgundy text-white' : 'text-earth/60 hover:bg-burgundy/5'}`}
            >
              <tab.icon size={12} /> {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-burgundy/5 overflow-hidden min-h-[600px]">
        {/* TAB: PRODOTTI */}
        {activeTab === 'products' && (
          <div className="overflow-x-auto">
             <div className="p-6 border-b border-burgundy/5 flex justify-between items-center bg-burgundy/[0.02]">
                <h2 className="font-serif text-xl text-burgundy italic">Catalogo Etichette</h2>
                <button onClick={handleAddNew} className="bg-burgundy text-white px-6 py-2 rounded text-[10px] font-bold uppercase tracking-widest hover:bg-gold transition-all flex items-center gap-2">
                  <Plus size={14} /> Nuova Etichetta
                </button>
             </div>
             <table className="w-full text-left">
                <thead className="bg-burgundy/5 text-[10px] uppercase font-bold tracking-widest text-earth/50 border-b border-burgundy/10">
                  <tr>
                    <th className="px-6 py-4">Etichetta</th>
                    <th className="px-6 py-4">Info Tecniche</th>
                    <th className="px-6 py-4">Prezzo</th>
                    <th className="px-6 py-4">Stock</th>
                    <th className="px-6 py-4 text-right">Azioni</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-burgundy/5">
                  {products.map(p => (
                    <tr key={p.id} className="hover:bg-burgundy/[0.01] transition-colors">
                      <td className="px-6 py-4 flex items-center gap-3">
                        <img src={p.image} className="w-10 h-14 object-contain bg-cream rounded border border-burgundy/5" alt={p.name} />
                        <div>
                          <p className="text-sm font-bold text-burgundy">{p.name}</p>
                          <p className="text-[10px] text-earth/40 uppercase tracking-tighter">{p.vintage} — {p.category}</p>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-[10px] text-earth/60 space-y-1">
                          <p>Uva: <span className="font-bold">{p.grape}</span></p>
                          <p>Alcol: <span className="font-bold">{p.alcohol}</span></p>
                        </div>
                      </td>
                      <td className="px-6 py-4 font-bold text-burgundy">€ {(p.priceInCents/100).toFixed(2)}</td>
                      <td className="px-6 py-4">
                        <span className={`text-[10px] font-bold uppercase px-2 py-1 rounded ${p.stock < 10 ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'}`}>
                          {p.stock} pz
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-1">
                          <button onClick={() => { setEditingProduct(p); setIsAddingNew(false); }} className="p-2 text-earth/40 hover:text-gold transition-colors"><Edit size={16}/></button>
                          <button onClick={() => deleteProduct(p.id)} className="p-2 text-earth/40 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
             </table>
          </div>
        )}

        {/* TAB: ORDINI */}
        {activeTab === 'orders' && (
          <div className="p-8 space-y-8">
            <h2 className="font-serif text-2xl text-burgundy italic">Archivio Ordini</h2>
            {orders.length === 0 ? <p className="text-center py-20 italic text-earth/40">Nessun ordine presente.</p> : (
              <div className="space-y-6">
