import React, { useState } from 'react';
import { Product, Order, Coupon, ShippingSettings, WineCategory, OrderStatus } from '../types';
import { Plus, Edit, Trash2, Save, X, Globe, CreditCard, Tag, ClipboardList, Package, DollarSign, Phone, MapPin, User as UserIcon, Wine, Image as ImageIcon, Info, GlassWater, Utensils, Mail, Truck, Clock, CheckCircle2 } from 'lucide-react';

interface AdminProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  coupons: Coupon[];
  setCoupons: React.Dispatch<React.SetStateAction<Coupon[]>>;
  shippingSettings: ShippingSettings;
  setShippingSettings: React.Dispatch<React.SetStateAction<ShippingSettings>>;
}

const Admin: React.FC<AdminProps> = ({ products, setProducts, orders, setOrders, coupons, setCoupons, shippingSettings, setShippingSettings }) => {
  const [activeTab, setActiveTab] = useState<'products' | 'orders' | 'coupons' | 'shipping' | 'payments'>('products');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [isAddingNew, setIsAddingNew] = useState(false);
  const [countryInput, setCountryInput] = useState('');
  const [orderFilter, setOrderFilter] = useState<'TO_PROCESS' | 'SHIPPED'>('TO_PROCESS');

  const [newCoupon, setNewCoupon] = useState({ code: '', discount: 0, type: 'PERCENT' as 'PERCENT' | 'FIXED' });
  const [stripeSettings, setStripeSettings] = useState({
    publicKey: 'pk_test_51Mz...',
    secretKey: 'sk_test_51Mz...',
    mode: 'test' as 'test' | 'live'
  });

  const handleAddNew = () => {
    const newProd: Product = {
      id: '',
      name: '',
      slug: '',
      vintage: new Date().getFullYear(),
      grape: '',
      category: 'Rosso',
      priceInCents: 0,
      stock: 0,
      image: '',
      lifestyleImage: '',
      isAvailable: true,
      sulfites: true,
      alcohol: '13.0%',
      allergens: 'Contiene solfiti',
      description: '',
      tastingNotes: { visual: '', olfactory: '', gustatory: '' },
      pairings: []
    };
    setEditingProduct(newProd);
    setIsAddingNew(true);
  };

  const saveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const productToSave = {
      ...editingProduct,
      slug: editingProduct.slug || editingProduct.name.toLowerCase().replace(/ /g, '-').replace(/[^\w-]+/g, '')
    };

    if (isAddingNew) {
      setProducts(prev => [...prev, { ...productToSave, id: Math.random().toString(36).substr(2, 9) }]);
    } else {
      setProducts(prev => prev.map(p => p.id === editingProduct.id ? productToSave : p));
    }
    setEditingProduct(null);
    setIsAddingNew(false);
  };

  const deleteProduct = (id: string) => {
    if (confirm("Sei sicuro di voler eliminare questo vino dal catalogo?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const addCoupon = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCoupon.code) return;
    const coupon: Coupon = {
      id: Math.random().toString(36).substr(2, 9),
      code: newCoupon.code.toUpperCase(),
      discount: newCoupon.discount,
      type: newCoupon.type
    };
    setCoupons(prev => [...prev, coupon]);
    setNewCoupon({ code: '', discount: 0, type: 'PERCENT' });
  };

  const deleteCoupon = (id: string) => {
    setCoupons(prev => prev.filter(c => c.id !== id));
  };

  const addCountry = () => {
    if (countryInput && !shippingSettings.supportedCountries.includes(countryInput)) {
      setShippingSettings({...shippingSettings, supportedCountries: [...shippingSettings.supportedCountries, countryInput]});
      setCountryInput('');
    }
  };

  const removeCountry = (c: string) => {
    setShippingSettings({...shippingSettings, supportedCountries: shippingSettings.supportedCountries.filter(country => country !== c)});
  };

  const handleShipOrder = (id: string) => {
    if (confirm("Vuoi segnare l'ordine come EVASO e spedito?")) {
      setOrders(prev => prev.map(o => o.id === id ? { ...o, status: OrderStatus.SHIPPED } : o));
    }
  };

  const filteredOrders = orders.filter(o => 
    orderFilter === 'TO_PROCESS' ? (o.status === OrderStatus.PAID || o.status === OrderStatus.PENDING) : o.status === OrderStatus.SHIPPED
  );

  const pendingCount = orders.filter(o => o.status === OrderStatus.PAID || o.status === OrderStatus.PENDING).length;
  const shippedCount = orders.filter(o => o.status === OrderStatus.SHIPPED).length;

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div className="space-y-2">
          <h1 className="text-4xl font-serif text-mustard italic">Console Admin</h1>
          <p className="text-lavender uppercase tracking-widest text-xs font-bold">Gestione Origini</p>
        </div>

        <div className="flex bg-white rounded-full p-1 shadow-md border border-mustard/10 overflow-x-auto">
          {[
            { id: 'products', label: 'Vini', icon: Package },
            { id: 'orders', label: 'Ordini', icon: ClipboardList },
            { id: 'coupons', label: 'Coupon', icon: Tag },
            { id: 'shipping', label: 'Logistica', icon: Globe },
            { id: 'payments', label: 'Pagamenti', icon: CreditCard }
          ].map(tab => (
            <button 
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)} 
              className={`flex items-center gap-2 px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-mustard text-white' : 'text-earth/60 hover:bg-mustard/5'}`}
            >
              <tab.icon size={12} /> {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-2xl border border-mustard/5 overflow-hidden min-h-[650px]">
        {/* TAB: PRODOTTI */}
        {activeTab === 'products' && (
          <div className="overflow-x-auto">
             <div className="p-8 border-b border-mustard/10 flex justify-between items-center bg-mustard/[0.02]">
                <h2 className="font-serif text-2xl text-mustard italic">Catalogo Etichette</h2>
                <button onClick={handleAddNew} className="bg-mustard text-white px-8 py-3 rounded text-[10px] font-bold uppercase tracking-widest hover:bg-lavender transition-all flex items-center gap-2 shadow-lg">
                  <Plus size={14} /> Nuova Etichetta
                </button>
             </div>
