                </div>
                <h3 className="font-brand-caps text-3xl font-bold tracking-tight text-white italic">ORIGINI</h3>
              </Link>
              <div className="text-[11px] text-white/70 leading-loose space-y-3 font-medium uppercase tracking-wider">
