                </div>
                <h3 className="font-brand-caps text-2xl font-bold tracking-tight text-white italic">ORIGINI SRL SOCIETÀ AGRICOLA</h3>
              </Link>
              <div className="text-[11px] text-white/70 leading-loose space-y-3 font-medium uppercase tracking-wider">
                <p className="flex items-start gap-3"><MapPin size={16} className="text-lavender shrink-0 mt-1" /> Contrada Mortella, 67, 66030 Poggiofiorito (CH)</p>
                <p className="flex items-center gap-3"><Phone size={16} className="text-lavender" /> 0871 198 1220 / 375 862 7573</p>
                <p className="flex items-center gap-3"><Mail size={16} className="text-lavender" /> <a href="mailto:info@terredelpoggio.it" className="hover:text-white transition-colors">info@terredelpoggio.it</a></p>
