                <h4 className="font-serif text-xl font-bold mb-6 text-lavender italic">Le Collezioni</h4>
                <ul className="space-y-3 text-xs uppercase font-bold tracking-widest text-white/60">
                  <li><Link to="/shop?cat=Rosso" className="hover:text-white transition-colors">Vini Rossi</Link></li>
                  <li><Link to="/shop?cat=Bianco" className="hover:text-white transition-colors">Vini Bianchi</Link></li>
