          </div>

          {/* Bottom Copyright */}
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-16 pt-8 border-t border-white/5 text-center text-[9px] text-white/30 uppercase tracking-[0.4em] font-bold">
            <p>© {new Date().getFullYear()} Origini Srl Società Agricola • Designed for Origini Collection</p>
          </div>
